using System;using System.Collections.Generic;using System.Data;using System.Linq;using Autodesk.Navisworks.Api;using NavisLegacyPlugin.Models.Execution;using NavisLegacyPlugin.Models.ExternalSources;using NavisLegacyPlugin.Models.Matching;using NavisLegacyPlugin.Models.Topology;using NavisLegacyPlugin.Services.Matching;
namespace NavisLegacyPlugin.Services.Topology
{
 public sealed class ExternalTopologyOutcome{public ExternalTopologyOutcome(int rowIndex,TransferMatchResult match,TopologyResolution resolution,bool conflict,IEnumerable<TransferOperationResult>operations){RowIndex=rowIndex;Match=match;Resolution=resolution;Conflict=conflict;Operations=(operations??Enumerable.Empty<TransferOperationResult>()).ToList().AsReadOnly();}public int RowIndex{get;private set;}public TransferMatchResult Match{get;private set;}public TopologyResolution Resolution{get;private set;}public bool Conflict{get;private set;}public IReadOnlyList<TransferOperationResult> Operations{get;private set;}}
 public sealed class ExternalTopologyTransferCoordinator
 {
  private readonly TopologyDropBCoordinator _coordinator; private readonly TopologyPathBuilder _paths=new TopologyPathBuilder();
  public ExternalTopologyTransferCoordinator(ComPropertyWriteService writer){var settings=new TopologyAlignmentSettings();_coordinator=new TopologyDropBCoordinator(new TopologyAnalysisService(settings),new TopologyConflictReconciler(),new TopologyBranchWriteExecutor(writer));}
  public IReadOnlyList<ExternalTopologyOutcome> Execute(ExternalSourcePopulation population,DataTable table,IEnumerable<ModelItem> targetItems,MatchStrategyDefinition strategy,bool overwrite)
  {
   var targets=(targetItems??Enumerable.Empty<ModelItem>()).Where(x=>x!=null).ToList();var resolver=new OrderedRowMatchResolver(targets,new[]{strategy});var sources=new List<TopologySourceGroup>();var rowByGroup=new Dictionary<string,int>();var matchByRow=new Dictionary<int,TransferMatchResult>();
   foreach(DataRow row in table.Rows){int i=Convert.ToInt32(row["__SourceRowIndex"]);var snap=population.Items[i];string rid=ReadColumn(row,"MAE-4D.RID");var m=resolver.Resolve(row);var tm=ToMatch(m);matchByRow[i]=tm;var anchors=new[]{new TopologyAnchorEvidence(strategy.Name,m.Key,ToAnchor(m.Status),m.Reason,FP(snap),m.Item==null?null:_paths.CreateFingerprint(m.Item))};var path=(snap.AncestorPath??new List<ExternalTopologyPathNodeSnapshot>()).Select(x=>new TopologyPathNode(x.DepthFromItem,x.DisplayName,new TopologyItemFingerprint(x.InstanceGuid,x.ItemGuid,x.SourceFile,x.DisplayName))).ToList();string id=i.ToString();sources.Add(new TopologySourceGroup(id,rid,FP(snap),path,anchors));rowByGroup[id]=i;}
   Func<TopologySourceGroup,IEnumerable<TopologyTargetCandidate>> provider=s=>targets.Select(t=>new TopologyTargetCandidate(t,_paths.CreateFingerprint(t),_paths.BuildFromAnchorToAncestors(t,Math.Max(1,s.SourcePath.Count))));var result=_coordinator.Execute(sources,provider,targets,overwrite);var writes=result.Writes.ToDictionary(x=>x.Plan,x=>x);var list=new List<ExternalTopologyOutcome>();
   foreach(var a in result.Analyses){int row=rowByGroup[a.Source.GroupId];bool conflict=result.Reconciliation.Blocked.Contains(a)&&a.Resolution.Status==TopologyResolutionStatus.Good&&a.SelectedCandidate!=null;var ops=new List<TransferOperationResult>();var plan=result.Reconciliation.Plans.FirstOrDefault(p=>p.Sources.Contains(a));if(plan!=null&&writes.ContainsKey(plan)){var w=writes[plan];ops.Add(new TransferOperationResult(w.Status,"PropertyWrite","MAE-4D","RID",a.Source.RidValue,w.Reason,w.Error));}list.Add(new ExternalTopologyOutcome(row,matchByRow[row],a.Resolution,conflict,ops));}
   return list.AsReadOnly();
  }
  private static string ReadColumn(DataRow r,string n){return r.Table.Columns.Contains(n)&&r[n]!=DBNull.Value?Convert.ToString(r[n]):string.Empty;} private static TopologyItemFingerprint FP(ExternalModelItemSnapshot s){string g=Prop(s,"Item","GUID"),f=Prop(s,"Item","Source File Name");if(string.IsNullOrWhiteSpace(f))f=Prop(s,"Item","Source File");return new TopologyItemFingerprint(s.InstanceGuid,g,f,s.DisplayName);} private static string Prop(ExternalModelItemSnapshot s,string c,string n){var p=s.Properties.FirstOrDefault(x=>x!=null&&string.Equals(x.Category,c,StringComparison.OrdinalIgnoreCase)&&string.Equals(x.Name,n,StringComparison.OrdinalIgnoreCase));return p==null?string.Empty:p.Value;} private static TopologyAnchorStatus ToAnchor(MatchResolutionStatus s){return s==MatchResolutionStatus.Matched?TopologyAnchorStatus.Matched:s==MatchResolutionStatus.Ambiguous?TopologyAnchorStatus.Ambiguous:s==MatchResolutionStatus.MissingKey?TopologyAnchorStatus.MissingKey:TopologyAnchorStatus.Unmatched;} private static TransferMatchResult ToMatch(MatchResolution m){TransferMatchStatus s=m.Status==MatchResolutionStatus.Matched?TransferMatchStatus.Matched:m.Status==MatchResolutionStatus.Ambiguous?TransferMatchStatus.Ambiguous:m.Status==MatchResolutionStatus.MissingKey?TransferMatchStatus.MissingKey:TransferMatchStatus.Unmatched;TransferTargetFingerprint f=m.Item==null?null:new TransferTargetFingerprint(m.Item.InstanceGuid.ToString("D"),string.Empty,string.Empty,m.Item.DisplayName);return new TransferMatchResult(s,m.StrategyName,m.Key,m.Reason,f);}
 }
}
